from taf.ul.trs_e2e_fw.lib.networking_devices.switch.switch_manager import SwitchManager


def configure_switch(device, command_profile, **kwargs):
    """

        _*Configure Switch*_  can be used to execute a command or execute and verify output of a command in a
          router/switch .

        *Usage*:
        Configure Switch <device>  <command_profile>


        | *arguments* | *comment* |
        | *device* | Name of the section in testline/testcase config file which contains the |
        |          | feilds  ip, port, make, password, enable_password, and configure_prompt. |
        | *command_profile* | Name of the section inside switch device  in the testline/testcase |
        |                   | config  json file which contains the commands. |

        *Example*
        | *keyword* | *device* | *command_profile* |
        | *Configure Switch* | *device1* | *test_commands* |
        | *Configure Switch* | *mwr_section* | *test_commands* |

        *Testline config  used can be seen at the top of this file*

        """
    SwitchManager().configure_switch(device, command_profile, **kwargs)
